// Recipe library: protein-rich, simple Romanian dishes with few, cheap ingredients found in any Romanian shop.
// Quantities are for ONE portion. Calories and macros are not typed in: they are computed from the ingredient
// values in foods.ts (USDA FoodData Central), so every number traces back to a food composition table.
// Salt, pepper, paprika, herbs (dill, parsley, lovage, thyme, bay leaf), vinegar, lemon, borș and mustard are
// assumed to be in the kitchen and are not counted (they add almost no calories).

export type RecipeCat = 'breakfast' | 'soup' | 'stew' | 'oven' | 'pan' | 'salad' | 'snack';

export interface LibRecipe {
  id: string;
  cat: RecipeCat;
  min: number; // total time, minutes
  ro: string;
  en: string;
  items: [string, number][]; // ingredient id, grams for one portion
  sRo: string[];
  sEn: string[];
}

export const CATS: { id: RecipeCat; ro: string; en: string; emoji: string }[] = [
  { id: 'breakfast', ro: 'Mic dejun', en: 'Breakfast', emoji: '🍳' },
  { id: 'soup', ro: 'Ciorbe și supe', en: 'Soups', emoji: '🥣' },
  { id: 'stew', ro: 'Mâncăruri', en: 'Stews', emoji: '🍲' },
  { id: 'oven', ro: 'Cuptor și grătar', en: 'Oven and grill', emoji: '🔥' },
  { id: 'pan', ro: 'Rapide (≤ 25 min)', en: 'Quick (≤ 25 min)', emoji: '⚡' },
  { id: 'salad', ro: 'Salate proteice', en: 'Protein salads', emoji: '🥗' },
  { id: 'snack', ro: 'Gustări și deserturi', en: 'Snacks and desserts', emoji: '🍮' },
];

/** Always assumed available, never counted as "missing" in the pantry match. */
export const STAPLES = new Set(['garlic']);
/** Interchangeable ingredients for the pantry match (having any one of the group counts). */
const SUB_GROUPS = [['chicken', 'chicken_thigh', 'turkey'], ['turkey_mince', 'beef_mince', 'pork_mince'], ['oil', 'olive_oil'], ['greek_yogurt', 'yogurt'], ['beans', 'beans_canned'], ['pork', 'beef'], ['hake', 'carp', 'trout'], ['telemea', 'cascaval'], ['cottage', 'urda']];
export const SUBS: Record<string, string[]> = Object.fromEntries(SUB_GROUPS.flatMap((g) => g.map((id) => [id, g.filter((x) => x !== id)])));
/** Side dishes that never block a match (bread, pickles). */
export const OPTIONAL = new Set(['bread_ww', 'pickles']);
